'use client'

import { FormEvent, useEffect, useMemo, useState } from 'react'
import { usePathname } from 'next/navigation'
import LoginPage from './login/page'

type Status = 'Completed' | 'Planned' | 'In progress' | 'Overdue'
type Priority = 'P1' | 'P2' | 'P3'
type Employee = { id: string; name: string; initials: string; role: string; unit: string; license: string; readiness: number; open: number; tone: string; email: string }
type Training = { id: any; course: string; type: string; priority: Priority; status: Status; due: string; owner: string; ownerId: string; evidence?: string; plannedDate?: string; completedDate?: string; createdAt?: string }
type Course = { id: number; name: string; type: string; cycle: string; owner: string; assigned: number; completion: number; required: boolean }
type Approval = { id: any; employee: string; item: string; kind: string; submitted: string; status: 'Pending' | 'Approved' | 'Returned' }
type Document = { id: string; trainingRecordId: string; fileName: string; reviewStatus: 'Pending' | 'Approved' | 'Returned'; createdAt: string; employeeId: string; course?: string }
type AssignmentNotification = { id: string; trainingRecordId: string; employeeId: string; course?: string; createdAt: string }

